#!/usr/bin/env python3
"""V7.3 Arena Perception in-app calibration and inspection page."""


def _replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} expected one match, found {count}")
    return text.replace(old, new, 1)


def apply_arena_perception_ui_patch(text):
    old = '''        self._action_button(header_actions, "CALIBRATE USER", self.capture_opponent_username_roi).pack(side="left", padx=(0, 7))\n        self._action_button(header_actions, "CALIBRATE ORG", self.capture_opponent_org_roi).pack(side="left", padx=(0, 7))\n        self._action_button(header_actions, "INTEL", self.open_intelligence).pack(side="left", padx=(0, 7))\n'''
    new = '''        self._action_button(header_actions, "CALIBRATE USER", self.capture_opponent_username_roi).pack(side="left", padx=(0, 7))\n        self._action_button(header_actions, "CALIBRATE ORG", self.capture_opponent_org_roi).pack(side="left", padx=(0, 7))\n        self._action_button(header_actions, "PERCEPTION", self.open_arena_perception).pack(side="left", padx=(0, 7))\n        self._action_button(header_actions, "INTEL", self.open_intelligence).pack(side="left", padx=(0, 7))\n'''
    text = _replace_once(text, old, new, "perception History entry")

    old = '''    def _show_roi_picker(self, ref, title, callback, instructions=None):\n'''
