    text = _replace_once(text, old, new, "configurable ROI picker signature")

    old = '''            if x2 - x1 < 20 or y2 - y1 < 20:\n                messagebox.showwarning(\n                    "Calibration",\n                    "Selection is too small."\n                )\n'''
    new = '''            if x2 - x1 < int(min_width) or y2 - y1 < int(min_height):\n                messagebox.showwarning(\n                    "Calibration",\n                    f"Selection is too small. Minimum {int(min_width)}x{int(min_height)} reference pixels."\n                )\n'''
    text = _replace_once(text, old, new, "configurable ROI picker minimum")

    old = '''    def capture_opponent_org_roi(self):\n'''
    new = '''    def _arena_perception_ref(self):\n        if self.engine.running and self.engine.vision_mode == "STREAM" and self.engine.vision:\n            try:\n                ref, age_ms, _ = self.engine.vision.get_latest()\n                if ref is not None and (age_ms is None or age_ms < 1500):\n                    return ref.copy()\n            except Exception:\n                pass\n        return self._phone_reference_screenshot()\n\n    def _perception_var(self, name, default="-"):\n        if not hasattr(self, "perception_vars"):\n            self.perception_vars = {}\n        var = self.perception_vars.get(name)\n        if var is None:\n            var = tk.StringVar(value=default)\n            self.perception_vars[name] = var\n        return var\n\n    def open_arena_perception(self):\n        if hasattr(self, "dashboard_main"):\n            self.dashboard_main.grid_remove()\n        for page_name in (\n            "history_page", "intelligence_page", "strategy_page",\n            "daily_page", "vision_page", "diagnostics_page",\n        ):\n            page = getattr(self, page_name, None)\n            if page is not None:\n                try:\n                    page.grid_remove()\n                except Exception:\n                    pass\n        old_page = getattr(self, "perception_page", None)\n        if old_page is not None:\n            try:\n                old_page.destroy()\n            except Exception:\n                pass\n\n        page = tk.Frame(self.shell, bg=UI_BG)\n        page.grid(row=0, column=1, sticky="nsew", padx=(26, 26), pady=(18, 18))\n        page.grid_columnconfigure(0, weight=1)\n        page.grid_rowconfigure(3, weight=1)\n        self.perception_page = page\n        self.perception_vars = {}\n        self._set_active_nav("history")\n\n        header = tk.Frame(page, bg=UI_BG)\n        header.grid(row=0, column=0, sticky="ew", pady=(0, 14))\n        header.grid_columnconfigure(0, weight=1)\n        left = tk.Frame(header, bg=UI_BG)\n        left.grid(row=0, column=0, sticky="w")\n        self._label(left, "Arena Perception", bg=UI_BG, size=18, weight="bold").pack(anchor="w")\n        self._label(\n            left,\n            "Calibrated Power + HP  •  opponent visual events  •  no guessed data",\n            bg=UI_BG, fg=UI_MUTED, size=9,\n        ).pack(anchor="w", pady=(2, 0))\n        actions = tk.Frame(header, bg=UI_BG)\n        actions.grid(row=0, column=1, sticky="e")\n        self._action_button(actions, "TEST", self.test_arena_perception).pack(side="left", padx=(0, 7))\n        self._action_button(actions, "HISTORY", self.open_history).pack(side="left", padx=(0, 7))\n        self._action_button(actions, "DASHBOARD", self._close_perception_dashboard).pack(side="left")\n\n        cards = tk.Frame(page, bg=UI_BG)\n        cards.grid(row=1, column=0, sticky="ew")\n        for c in range(3):\n            cards.grid_columnconfigure(c, weight=1, uniform="perception")\n\n        power_card, power = self._make_card(cards, padx=14, pady=12)\n        power_card.grid(row=0, column=0, sticky="nsew", padx=(0, 6))\n        self._label(power, "OPPONENT POWER", fg=UI_MUTED, size=8).pack(anchor="w")\n        self._label(power, textvariable=self._perception_var("power"), size=10, weight="bold").pack(anchor="w", pady=(6, 8))\n        self._action_button(power, "CALIBRATE POWER", self.capture_opponent_power_roi).pack(fill="x")\n\n        hp_card, hp = self._make_card(cards, padx=14, pady=12)\n        hp_card.grid(row=0, column=1, sticky="nsew", padx=6)\n        self._label(hp, "BATTLE HP", fg=UI_MUTED, size=8).pack(anchor="w")\n        self._label(hp, textvariable=self._perception_var("hp"), size=10, weight="bold").pack(anchor="w", pady=(6, 8))\n        self._action_button(hp, "CALIBRATE 6 HP BARS", self.capture_battle_hp_rois).pack(fill="x")\n\n        move_card, move = self._make_card(cards, padx=14, pady=12)\n        move_card.grid(row=0, column=2, sticky="nsew", padx=(6, 0))\n        self._label(move, "ENEMY EVENT AREA", fg=UI_MUTED, size=8).pack(anchor="w")\n        self._label(move, textvariable=self._perception_var("move"), size=10, weight="bold").pack(anchor="w", pady=(6, 8))\n        self._action_button(move, "CALIBRATE EVENT AREA", self.capture_opponent_move_roi).pack(fill="x")\n\n        live_card, live = self._make_card(page, padx=14, pady=12)\n        live_card.grid(row=2, column=0, sticky="ew", pady=(14, 0))\n        live_top = tk.Frame(live, bg=UI_CARD)\n        live_top.pack(fill="x")\n        self._label(live_top, "Perception Test", size=10, weight="bold").pack(side="left")\n        self._label(live_top, textvariable=self._perception_var("test"), fg=UI_BLUE, size=8, weight="bold").pack(side="right")\n        self._label(\n            live,\n            "Power and HP remain UNKNOWN until explicitly calibrated. HP collapse can only accelerate an already-learned loss prediction; it cannot surrender by itself.",\n            fg=UI_MUTED, size=8, wraplength=900, justify="left",\n        ).pack(anchor="w", pady=(8, 0))\n\n        events_card, events = self._make_card(page, padx=14, pady=12)\n        events_card.grid(row=3, column=0, sticky="nsew", pady=(14, 0))\n        event_head = tk.Frame(events, bg=UI_CARD)\n        event_head.pack(fill="x")\n        self._label(event_head, "Learned Enemy Move / Card Signatures", size=10, weight="bold").pack(side="left")\n        self._action_button(event_head, "LABEL EVENT", self.label_arena_event).pack(side="right")\n        self._label(\n            events,\n            "Unknown animations stay EVT-xxxx until you verify and label them. Evidence JPGs are saved in AppData/arena_event_samples.",\n            fg=UI_MUTED, size=8,\n        ).pack(anchor="w", pady=(5, 8))\n        self.perception_event_text = tk.Text(\n            events, height=10, bg=UI_CARD, fg=UI_MUTED, insertbackground=UI_TEXT,\n            relief="flat", bd=0, highlightthickness=0, font=("Consolas", 8), wrap="word",\n        )\n        self.perception_event_text.pack(fill="both", expand=True)\n        self.perception_event_text.config(state="disabled")\n        self.refresh_arena_perception_page()\n\n    def _close_perception_dashboard(self):\n        page = getattr(self, "perception_page", None)\n        if page is not None:\n            try:\n                page.destroy()\n            except Exception:\n                pass\n            self.perception_page = None\n        self.show_dashboard()\n\n    def refresh_arena_perception_page(self):\n        settings = get_opponent_settings()\n        power_roi = opponent_power_roi()\n        ally_rois = battle_hp_rois("ally")\n        enemy_rois = battle_hp_rois("enemy")\n        move_custom = _normalized_opponent_roi(settings.get("move_roi"), 80, 60)\n        self._perception_var("power").set(\n            "CALIBRATED" if power_roi is not None else "NOT CALIBRATED"\n        )\n        self._perception_var("hp").set(\n            f"Ally {len(ally_rois)}/3  •  Enemy {len(enemy_rois)}/3"\n        )\n        self._perception_var("move").set(\n            "CUSTOM ROI" if move_custom is not None else "DEFAULT ENEMY AREA"\n        )\n        rows = arena_event_summary(30)\n        lines = []\n        for row in rows:\n            label = str(row.get("label") or "UNLABELED")\n            wr = row.get("win_rate")\n            wr_text = f"{wr:.0f}% WR" if wr is not None else "WR ?"\n            lines.append(\n                f"{row['id']:<9} {label:<24} seen={row['count']:<4} "\n                f"matches={row['matches']:<3} {row['wins']}W/{row['losses']}L {wr_text:<7} "\n                f"evidence={row.get('evidence') or '-'}"\n            )\n        widget = getattr(self, "perception_event_text", None)\n        if widget is not None:\n            widget.config(state="normal")\n            widget.delete("1.0", "end")\n            widget.insert("1.0", "\\n".join(lines) if lines else "No enemy event clusters learned yet.")\n            widget.config(state="disabled")\n\n    def capture_opponent_power_roi(self):\n        if self.engine.running:\n            messagebox.showwarning("Stop grinder first", "Stop Arena Bot before Power calibration.")\n            return\n        if not messagebox.askokcancel(\n            "Calibrate Opponent Power",\n            "Put the phone on the Arena opponent/opening screen where the opponent Power/CP number is clearly visible.\\n\\nThen select ONLY that number/value area."\n        ):\n            return\n        try:\n            ref = self._phone_reference_screenshot()\n        except Exception as exc:\n            messagebox.showerror("Power Calibration", str(exc))\n            return\n        def save_roi(x1, y1, x2, y2):\n            update_opponent_setting("power_roi", [x1, y1, x2, y2])\n            value, conf, raw = read_opponent_power(ref)\n            self.add_log(f"Arena Perception: Power ROI {x1},{y1}->{x2},{y2} • read={value} raw={raw!r}")\n            self.refresh_arena_perception_page()\n            if value is None:\n                messagebox.showwarning(\n                    "Power ROI Saved",\n                    "ROI saved, but the current screenshot did not produce a reliable Power value.\\n\\nUse TEST with the number clearly visible before relying on it."\n                )\n            else:\n                messagebox.showinfo(\n                    "Power Calibration",\n                    f"Detected Power: {value:,}\\nOCR confidence: {conf:.0f}%" if conf is not None else f"Detected Power: {value:,}"\n                )\n        self._show_roi_picker(\n            ref, "Opponent Power / CP", save_roi,\n            instructions="Drag tightly around ONLY the opponent Power/CP number.",\n            min_width=24, min_height=10,\n        )\n\n    def capture_battle_hp_rois(self):\n        if self.engine.running:\n            messagebox.showwarning("Stop grinder first", "Stop Arena Bot before HP-bar calibration.")\n            return\n        if not messagebox.askokcancel(\n            "Calibrate Battle HP",\n            "Put the phone inside a normal Arena battle with all 3 ally and all 3 enemy HP bars visible.\\n\\nYou will select six bars in order. Select the FULL bar rectangle, including its empty/background portion."\n        ):\n            return\n        try:\n            ref = self._phone_reference_screenshot()\n        except Exception as exc:\n            messagebox.showerror("HP Calibration", str(exc))\n            return\n        sequence = [\n            ("ALLY 1", "ally"), ("ALLY 2", "ally"), ("ALLY 3", "ally"),\n            ("ENEMY 1", "enemy"), ("ENEMY 2", "enemy"), ("ENEMY 3", "enemy"),\n        ]\n        picked = {"ally": [], "enemy": []}\n        def pick_index(index):\n            if index >= len(sequence):\n                update_opponent_setting("ally_hp_rois", picked["ally"])\n                update_opponent_setting("enemy_hp_rois", picked["enemy"])\n                snap = _arena_hp_snapshot(ref)\n                self.add_log(f"Arena Perception: HP bars calibrated • {snap}")\n                self.refresh_arena_perception_page()\n                ally_text = ", ".join(f"{x:.0%}" for x in snap.get("ally") or []) or "?"\n                enemy_text = ", ".join(f"{x:.0%}" for x in snap.get("enemy") or []) or "?"\n                messagebox.showinfo(\n                    "HP Calibration Complete",\n                    f"Initial read\\nAlly: {ally_text}\\nEnemy: {enemy_text}\\n\\nRun TEST on another battle state to verify the ratios change sensibly."\n                )\n                return\n            label, side = sequence[index]\n            def saved(x1, y1, x2, y2):\n                picked[side].append([x1, y1, x2, y2])\n                self.root.after(80, lambda: pick_index(index + 1))\n            self._show_roi_picker(\n                ref, f"HP Bar {label}", saved,\n                instructions=f"{index + 1}/6 — drag around the FULL {label} HP bar, not the portrait or name.",\n                min_width=28, min_height=5,\n            )\n        pick_index(0)\n\n    def capture_opponent_move_roi(self):\n        if self.engine.running:\n            messagebox.showwarning("Stop grinder first", "Stop Arena Bot before event-area calibration.")\n            return\n        if not messagebox.askokcancel(\n            "Calibrate Enemy Event Area",\n            "Put the phone in an Arena battle. Select the area where ENEMY skill/card/attack visuals consistently appear.\\n\\nDo not include your own card hand or AUTO button."\n        ):\n            return\n        try:\n            ref = self._phone_reference_screenshot()\n        except Exception as exc:\n            messagebox.showerror("Event Area", str(exc))\n            return\n        def save_roi(x1, y1, x2, y2):\n            update_opponent_setting("move_roi", [x1, y1, x2, y2])\n            self.add_log(f"Arena Perception: enemy event ROI {x1},{y1}->{x2},{y2}")\n            self.refresh_arena_perception_page()\n            messagebox.showinfo(\n                "Event Area Saved",\n                "Saved. Unknown opponent animations will be clustered as EVT-xxxx and kept unlabeled until verified."\n            )\n        self._show_roi_picker(\n            ref, "Enemy Move / Card Event Area", save_roi,\n            instructions="Drag around the enemy-side area where skills/cards/attack visuals appear.",\n            min_width=80, min_height=60,\n        )\n\n    def test_arena_perception(self):\n        try:\n            ref = self._arena_perception_ref()\n            power, conf, raw = read_opponent_power(ref)\n            hp = _arena_hp_snapshot(ref)\n            sig = _arena_event_signature(ref)\n            nearest_id = None\n            nearest_bits = 65\n            state = get_arena_learning_state()\n            for cluster_id, node in (state.get("event_clusters") or {}).items():\n                old_sig = _arena_event_signature_from_node(node)\n                bits = _arena_event_hamming(sig, old_sig)\n                if bits < nearest_bits:\n                    nearest_id, nearest_bits = str(cluster_id), int(bits)\n            power_text = f"{power:,}" if power is not None else "UNKNOWN"\n            ally_text = ", ".join(f"{x:.0%}" for x in hp.get("ally") or []) or "UNCALIBRATED"\n            enemy_text = ", ".join(f"{x:.0%}" for x in hp.get("enemy") or []) or "UNCALIBRATED"\n            event_text = f"{nearest_id} (d={nearest_bits})" if nearest_id is not None else "no learned cluster"\n            summary = f"Power {power_text} • Ally HP {ally_text} • Enemy HP {enemy_text} • Event {event_text}"\n            self._perception_var("test").set(summary[:150])\n            self.add_log(f"ARENA PERCEPTION TEST: {summary} • OCR raw={raw!r}")\n            self.refresh_arena_perception_page()\n            messagebox.showinfo(\n                "Arena Perception Test",\n                f"Power: {power_text}\\nPower OCR confidence: {conf:.0f}%" + ("" if conf is not None else " (unknown)") +\n                f"\\nAlly HP: {ally_text}\\nEnemy HP: {enemy_text}\\nNearest event: {event_text}"\n            )\n        except Exception as exc:\n            messagebox.showerror("Arena Perception Test", str(exc))\n\n    def label_arena_event(self):\n        rows = arena_event_summary(1000)\n        if not rows:\n            messagebox.showinfo("Label Event", "No learned enemy events yet.")\n            return\n        available = ", ".join(row["id"] for row in rows[:20])\n        cluster_id = simpledialog.askstring(\n            "Label Enemy Event",\n            "Cluster ID to label (example EVT-0001):\\n" + available,\n            parent=self.root,\n        )\n        if not cluster_id:\n            return\n        cluster_id = cluster_id.strip().upper()\n        state = get_arena_learning_state()\n        node = (state.get("event_clusters") or {}).get(cluster_id)\n        if not isinstance(node, dict):\n            messagebox.showerror("Label Event", f"Unknown cluster {cluster_id}.")\n            return\n        label = simpledialog.askstring(\n            "Verified Move / Card Name",\n            f"Enter the name ONLY if you verified what {cluster_id} represents.\\nEvidence: {node.get('evidence') or 'none'}",\n            initialvalue=str(node.get("label") or ""),\n            parent=self.root,\n        )\n        if label is None:\n            return\n        label = label.strip()[:80]\n        with ARENA_LEARNING_LOCK:\n            live = arena_learning_state.setdefault("event_clusters", {}).get(cluster_id)\n            if isinstance(live, dict):\n                live["label"] = label or None\n                live["labeled_at"] = datetime.now().isoformat(timespec="seconds") if label else None\n        save_arena_learning_state()\n        self.add_log(f"Arena Event: {cluster_id} labeled {label!r}" if label else f"Arena Event: {cluster_id} label cleared")\n        self.refresh_arena_perception_page()\n\n    def capture_opponent_org_roi(self):\n'''
    text = _replace_once(text, old, new, "perception UI methods")

    marker = "\n# V7.3 Arena Perception UI — guided Power/HP/event calibration build marker\n"
    if marker.strip() not in text:
        text += marker
    return text
